// What `npm run generate` derives of an aggregate: its repository and the handlers of its pattern commands, from the
// records and the aggregate's shape. On Lathe itself: every record a generated file holds is generated by the tooling
// record that writes it, and each generated handler is the one its definition takes. On a small slice of records:
// the code written for each command and the repository, and the refusal of a command the pattern cannot say.
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { afterAll, describe, expect, it } from 'vitest';
import { GENERATOR } from '../scripts/generate/aggregates.ts';
import { HANDLERS_FILE, readIdentities } from '../scripts/generate/identities.ts';
import { GENERATED_HEADER } from '../scripts/generate/output.ts';
import { generatedFiles } from '../scripts/generate/outputs.ts';
import { PACKAGE_DIR } from '../src/index.ts';

const REPO = path.join(PACKAGE_DIR, '..');
type Row = Record<string, unknown>;
const rows = (repo: string, table: string): Row[] => {
  const file = path.join(repo, 'data', `${table}.jsonl`);
  return existsSync(file) ? readFileSync(file, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l) as Row) : [];
};

describe('LA-STD-CODE-R13-T01 every record a generated file holds is generated by the tooling record that writes it, and each generated handler is its definition\'s', () => {
  it('links each technical record whose file the generator writes from the generator, and the generator to nothing else', () => {
    const generatedFile = (file: unknown) => typeof file === 'string' && file.endsWith('.ts') && existsSync(path.join(REPO, file)) && readFileSync(path.join(REPO, file), 'utf8').startsWith(GENERATED_HEADER);
    const tables = readdirSync(path.join(REPO, 'data')).map((f) => f.replace(/\.jsonl$/, ''));
    const inFile = tables.flatMap((t) => rows(REPO, t).filter((r) => typeof r.id === 'string' && generatedFile(r.file)).map((r) => String(r.id)));
    // An endpoint has no file: its method and route are its handler's generated identity, so it is generated with it.
    const handled = new Set(rows(REPO, 'endpoint_handler').filter((h) => inFile.includes(String(h.id))).map((h) => String(h.endpoint_id)));
    const held = [...inFile, ...rows(REPO, 'endpoint').map((e) => String(e.id)).filter((id) => handled.has(id))];
    const linked = rows(REPO, 'generates').filter((g) => g.source_id === GENERATOR).map((g) => String(g.target_id));
    expect(linked.filter((id) => !held.includes(id))).toEqual([]);
    expect(held.filter((id) => !linked.includes(id))).toEqual([]);
    const rowTypes = rows(REPO, 'data_model').filter((d) => d.file === 'lathe/src/platform/data/tables.ts').map((d) => String(d.id)).sort();
    expect(rows(REPO, 'generates').filter((g) => g.source_id === 'LA-AUT-TOOL01').map((g) => String(g.target_id)).sort()).toEqual(rowTypes);
  });

  it('gives each command whose handler is generated that handler, imported from its slice\'s generated handlers, with none of its own', () => {
    const generated = readIdentities(REPO).filter((d) => d.kind === 'command' && d.handlerFile.endsWith(`/commands/${HANDLERS_FILE}`));
    expect(generated.length).toBeGreaterThan(100);
    const wrong = generated.flatMap((d) => {
      const text = readFileSync(path.join(REPO, d.file), 'utf8');
      return [
        ...(text.includes(`import { ${d.handler} } from './${HANDLERS_FILE}';`) ? [] : [`${d.file} does not take ${d.handler} from ${HANDLERS_FILE}`]),
        ...(new RegExp(`^export function ${d.handler}\\(`, 'm').test(text) ? [`${d.file} writes ${d.handler} by hand`] : []),
      ];
    });
    expect(wrong).toEqual([]);
  });
});

describe('LA-STD-CODE-R13-T02 an aggregate\'s repository and its pattern commands\' handlers are generated from its shape, and a command the pattern cannot say is refused', () => {
  const lines = (list: object[]) => `${list.map((r) => JSON.stringify(r)).join('\n')}\n`;
  const repo = mkdtempSync(path.join(tmpdir(), 'lathe-generate-aggregates-'));
  const dir = 'lathe/src/demo/view';
  const handlers = `${dir}/commands/${HANDLERS_FILE}`;
  // One slice of the real View kinds: an Add, a Change and a Remove, its repository, and the tooling record that generates them.
  const commands = [
    { n: 1, name: 'add-view-requirement', title: 'Add a view requirement', entity: 'XX-EN2', handler: 'addViewRequirement', type: 'AddViewRequirement', input: ["id: column('view_requirement', 'id', 'required')", "title: column('view_requirement', 'title', 'required')", "view_id: column('view_requirement', 'view_id', 'required')"] },
    { n: 2, name: 'change-view-test', title: 'Change a view test', entity: 'XX-EN3', handler: 'changeViewTest', type: 'ChangeViewTest', input: ["id: column('view_test', 'id', 'required')", "title: column('view_test', 'title', 'optional')", "notes: column('view_test', 'notes', 'clearable')", "starts_from: ids('The test data sets it starts from. Replaces the list.', 'optional')"] },
    { n: 3, name: 'remove-view-requirement', title: 'Remove a view requirement', entity: 'XX-EN2', handler: 'removeViewRequirement', type: 'RemoveViewRequirement', input: ["id: column('view_requirement', 'id', 'required')"] },
    { n: 4, name: 'add-view-test', title: 'Add a view test', entity: 'XX-EN3', handler: 'addViewTest', type: 'AddViewTest', input: ["id: column('view_test', 'id', 'required')", "view_requirement_id: column('view_test', 'view_requirement_id', 'required')", "starts_from: ids('The test data sets it starts from.', 'optional')"] },
  ];
  const definition = (c: (typeof commands)[number], input = c.input) => `export const ${c.handler.replace(/[A-Z]/g, (l) => `_${l}`).toUpperCase()} = {
  ...IDENTITY,
  input: {
${input.map((f) => `    ${f},`).join('\n')}
  },
  handler: ${c.handler},
} satisfies CommandDefinition<${c.type}>;
`;
  const tables: Record<string, object[]> = {
    entity: [{ id: 'XX-EN1', aggregate_id: 'XX-A1' }, { id: 'XX-EN2', aggregate_id: 'XX-A1' }, { id: 'XX-EN3', aggregate_id: 'XX-A1' }],
    table: [{ id: 'XX-EN1-TB', entity_id: 'XX-EN1', name: 'view' }, { id: 'XX-EN2-TB', entity_id: 'XX-EN2', name: 'view_requirement' }, { id: 'XX-EN3-TB', entity_id: 'XX-EN3', name: 'view_test' }],
    command: commands.map((c) => ({ id: `XX-CMD${c.n}`, title: c.title, entity_id: c.entity, description: `${c.title.replace(/^(\w+) a/, '$1s a')}.` })),
    command_handler: commands.map((c) => ({ id: `XX-CMD${c.n}-H`, command_id: `XX-CMD${c.n}`, title: c.handler, file: handlers })),
    cli_command: commands.map((c) => ({ id: `XX-CMD${c.n}-CLI`, command_id: `XX-CMD${c.n}`, title: `lathe view ${c.name}`, mcp_tool: `view_${c.name.replaceAll('-', '_')}` })),
    endpoint: commands.map((c) => ({ id: `XX-EP${c.n}`, command_id: `XX-CMD${c.n}`, title: `POST /api/view/${c.name}`, method: 'POST', route: `/api/view/${c.name}` })),
    endpoint_handler: commands.map((c) => ({ id: `XX-EP${c.n}-H`, endpoint_id: `XX-EP${c.n}`, title: `${c.handler.replace(/[A-Z]/g, (l) => `_${l}`).toUpperCase()}_IDENTITY`, file: `${dir}/commands/identities.generated.ts` })),
    repository: [{ id: 'XX-REPO1', title: 'ViewRepository', file: `${dir}/repository.ts`, description: 'Loads and saves a view whole.' }],
    generates: [...commands.map((c) => ({ source_id: GENERATOR, target_id: `XX-CMD${c.n}-H` })), { source_id: GENERATOR, target_id: 'XX-REPO1' }],
  };
  mkdirSync(path.join(repo, 'data'));
  for (const [name, list] of Object.entries(tables)) writeFileSync(path.join(repo, 'data', `${name}.jsonl`), lines(list));
  mkdirSync(path.join(repo, dir, 'commands'), { recursive: true });
  writeFileSync(path.join(repo, dir, 'model.ts'), `export const VIEW_SHAPE = {
  view: { at: 'view' },
  view_requirement: { at: 'requirements' },
  view_test: { at: 'tests', lists: { starts_from: 'startsFrom' } },
} as const;
`);
  writeFileSync(path.join(repo, dir, 'rules.ts'), 'export function holdToRules(): void {}\n');
  for (const c of commands) writeFileSync(path.join(repo, dir, 'commands', `${c.name}.ts`), definition(c));
  afterAll(() => rmSync(repo, { recursive: true, force: true }));

  it('writes each command\'s handler specific to its kind, and the repository that loads what holds any of its kinds', async () => {
    const files = await generatedFiles(repo);
    const code = files.get(handlers)!;
    expect(code.startsWith(GENERATED_HEADER)).toBe(true);
    expect(code).toContain("import type { AddViewRequirement } from './add-view-requirement.ts';");
    expect(code).toContain(`/** Adds a view requirement. */
export function addViewRequirement(tx: Transaction, input: AddViewRequirement): void {
  const views = new ViewRepository(tx);
  const view = views.load(input.view_id) ?? tx.refuse('missing', \`there is no view \${input.view_id}\`);
  view.requirements.push(input);
  holdToRules(tx, view);
  views.save(view);
}`);
    expect(code).toContain(`  view.tests = view.tests.map((x) => (x.row.id === input.id ? { row: changed(x.row, input, ['title', 'notes']), startsFrom: input.starts_from ?? x.startsFrom } : x));`);
    expect(code).toContain(`export function removeViewRequirement(tx: Transaction, input: RemoveViewRequirement): void {
  const views = new ViewRepository(tx);
  const view = views.loadHolding('view_requirement', input.id) ?? tx.refuse('missing', \`there is no view requirement \${input.id}\`);
  view.requirements = view.requirements.filter((x) => x.id !== input.id);
  view.tests = view.tests.filter((x) => x.row.view_requirement_id !== input.id);
  views.save(view);
}`);
    const repository = files.get(`${dir}/repository.ts`)!;
    expect(repository).toContain('export class ViewRepository extends Repository<View> {');
    expect(repository).toContain("      case 'view_test': return this.rootOf('view_requirement', String(row.view_requirement_id));");
    expect(repository).toContain("    case 'view_test': return view.tests.some((x) => x.row.id === id);");
  });

  // Each shape in a copy of the slice of its own: a model, once loaded, is not loaded again.
  const copies: string[] = [];
  afterAll(() => copies.forEach((c) => rmSync(c, { recursive: true, force: true })));
  const withTest = (test: string) => {
    const copy = mkdtempSync(path.join(tmpdir(), 'lathe-generate-aggregates-'));
    copies.push(copy);
    cpSync(repo, copy, { recursive: true });
    writeFileSync(path.join(copy, dir, 'model.ts'), `export const VIEW_SHAPE = {
  view: { at: 'view' },
  view_requirement: { at: 'requirements' },
  view_test: ${test},
} as const;
`);
    return generatedFiles(copy);
  };

  it('refuses an Add that breaks its kind\'s rule over its rows (refusedBy), and an Add of a kind held at most once that names no such rule', async () => {
    let code = (await withTest("{ at: 'tests', refusedBy: 'testPerDomain', lists: { starts_from: 'startsFrom' } }")).get(handlers)!;
    expect(code).toContain("import { holdToRules, testPerDomain } from '../rules.ts';");
    expect(code).toContain(`  view.tests.push({ row, startsFrom: starts_from });
  refuseBroken(testPerDomain(view.tests.map((x) => x.row)));
  holdToRules(tx, view);`);
    expect(code).toContain(`: x));
  refuseBroken(testPerDomain(view.tests.map((x) => x.row)));`);

    code = (await withTest("{ at: 'test', one: true, refusedBy: 'oneTest', lists: { starts_from: 'startsFrom' } }")).get(handlers)!;
    expect(code).toContain(`  const { starts_from = [], ...row } = input;
  refuseBroken(oneTest([...(view.test ? [view.test.row] : []), row]));
  view.test = { row, startsFrom: starts_from };`);

    await expect(withTest("{ at: 'test', one: true, lists: { starts_from: 'startsFrom' } }")).rejects.toThrow(
      `XX-CMD4's handler cannot be generated: an Add of a kind held at most once refuses a second one: name the rule that does in VIEW_SHAPE.view_test.refusedBy. Write it by hand, in ${dir}/commands/add-view-test.ts`,
    );
  });

  it('refuses a command whose input the pattern cannot say, naming what and where to write it by hand', async () => {
    writeFileSync(path.join(repo, dir, 'commands', 'add-view-requirement.ts'), definition(commands[0], [...commands[0].input, "flow_id: column('flow', 'id', 'optional')", "hears: id('An event.', 'optional')"]));
    await expect(generatedFiles(repo)).rejects.toThrow(
      `XX-CMD1's handler cannot be generated: its field flow_id is a column of flow, not of view_requirement; its field hears is none of VIEW_SHAPE.view_requirement's lists or links. Write it by hand, in ${dir}/commands/add-view-requirement.ts`,
    );
  });
});
